import { AddonItemV2Style } from './index.style'
import { Fragment } from 'react'
import AddonItem from '../AddonItem/index'
import { get } from 'lodash/object'

function AddonItemV2 ({ addonCategory = {}, addonsState, hidePremium, onSelectedItem, onCalculatePremium }) {
  return (
    <AddonItemV2Style key={addonCategory.category_code}>
      <div className='category-name'>
        {addonCategory.category_name}
      </div>
      {
        addonCategory.add_on.map((item, index) => {
          if (!get(addonsState[addonCategory.category_name], 'driver-insurance', '') && item.add_on_code === 'passenger-insurance') return null
          return (
            <Fragment key={item.add_on_code}>
              <AddonItem
                item={item}
                hidePremium={hidePremium}
                selectedItem={addonsState[addonCategory.category_name] && addonsState[addonCategory.category_name][item.add_on_code]}
                onSelectItem={(addonItem, actionType) => onSelectedItem(addonCategory, addonItem, actionType)}
                onPremiumCalculation={(addon) => onCalculatePremium(addonCategory, addon)}
              />
              {
                (index + 1 !== addonCategory.add_on.length) && <div className='separator' />
              }
            </Fragment>
          )
        })
      }
    </AddonItemV2Style>
  )
}

export default AddonItemV2
