import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { usePolicyAddonsContextValue } from '../../context'
import { useCallback } from 'react'
import {
  getAddonsData, getCalculatedAddonPremium, resetAddonState,
  getProviderAddons, getAllAddonsData, getProductPkgAddonsReq
} from '../actions'

export const useAddonsServiceCall = (actionsCall = () => {}) => {
  const [addonsState, dispatch] = usePolicyAddonsContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback(async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])

  return [addonsState, request]
}

export const useResetAddonState = () => {
  const [, dispatch] = usePolicyAddonsContextValue()
  const resetState = (payload) => {
    dispatch(resetAddonState(payload))
  }
  return resetState
}

// get MV Addons Data
export const useGetAddons = () => useAddonsServiceCall(getAddonsData)

// get All addons data
export const useGetAllAddons = () => useAddonsServiceCall(getAllAddonsData)

// pkg list addons data
export const useGetProductPkgAddons = () => useAddonsServiceCall(getProductPkgAddonsReq)

// get provider addons Data
export const useGetProviderAddons = () => useAddonsServiceCall(getProviderAddons)

// calculate Addon Premium
export const useCalculateAddonPremium = () => useAddonsServiceCall(getCalculatedAddonPremium)
