import { Component } from 'react'
import PropTypes from 'prop-types'
import { QuantityStyle, QuantityCircle } from './index.style'

class QuantityAddRemove extends Component {
  static propTypes = {
    quantity: PropTypes.number,
    onUpdateQty: PropTypes.func,
    max: PropTypes.number,
    min: PropTypes.number
  }

  handleAddSub = counter => {
    // counter < 0 means minus and counter > 0 means add
    const { quantity = 0, min, max, onUpdateQty } = this.props
    const updateQty = quantity + (counter)
    if (updateQty < min) {
      // disable the minus(-) btn
      return false
    } else if (updateQty > max) {
      // disable add(+) btn
      return true
    }

    // update the qty
    onUpdateQty(updateQty)
  }

  render () {
    const { quantity = 0, min, max, className } = this.props
    return (
      <QuantityStyle className={className}>
        <QuantityCircle
          disabled={quantity === min}
          onClick={e => this.handleAddSub(-1)}
        >
          <i className='fas fa-minus' />
        </QuantityCircle>
        <div className='quantity-text'>{quantity}</div>
        <QuantityCircle
          disabled={quantity === max}
          onClick={e => this.handleAddSub(1)}
        >
          <i className='fas fa-plus' />
        </QuantityCircle>
      </QuantityStyle>
    )
  }
}

export default QuantityAddRemove
